entries[435145] = { ["name"] = "Bloody Skyscreamer", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"This dinosaur still harbors the rage of its ancestors from the Zandalari Invasion.\"\nWorld Event:\nWoW Remix: Mists of Pandaria" }
entries[435146] = { ["name"] = "Night Pterrorwing", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"Scholars interpret this creature's awful screeching as \"fear me, I am the night!\"\"\nWorld Event:\nWoW Remix: Mists of Pandaria" }
entries[435147] = { ["name"] = "Jade Pterrordax", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"This favored mount of the Zandalari is a great singer, or so it thinks.\"\nWorld Event:\nWoW Remix: Mists of Pandaria" }
