entries[435149] = { ["name"] = "Cobalt Juggernaut", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"What started as a rideable mining and logging machine devolved quickly into chaos when engineers asked themselves if they could make it any cooler.\"\nWorld Event:\nWoW Remix: Mists of Pandaria" }
entries[435150] = { ["name"] = "Fel Iron Juggernaut", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"This war machine was stolen from a timeline in which Garrosh Hellscream joined the Burning Legion. Suffice it to say, there is not much left of that timeline.\"\nWorld Event:\nWoW Remix: Mists of Pandaria" }
entries[435151] = { ["name"] = "Eye of the Swarm", ["text"] = "Unlimited range\nInstant\nUpon reaching 100 energy, Anub’zekt calls forth a massive swarm surrounding the arena. While within the biting insect swarm, players rapidly gain applications of Ceaseless Swarm." }
