entries[435330] = { ["name"] = "Ominous Energy Crystal", ["text"] = "2 sec cast\nTools: Jeweler's Tools\nReagents:\nCrushed Gemstones (5)\nOptional Reagents:\nVendor:\nAlvus Valavulu\nZone:\nCity of Threads\nCost:\n150\n1500\n\nOminous Energy Crystal\nFinishing Crafting Reagent\n\nWhen crafting: Increases Ingenuity by 300.\nUsable with: Many Jewelcrafting recipes except gem cuts. Engineers seem interested in this, too.\n\"Can be bought and sold on the Auction House.\"" }
entries[435331] = { ["name"] = "Elemental Focusing Lens", ["text"] = "2 sec cast\nTools: Jeweler's Tools\nReagents:\nNull Stone , Decorative Lens\nOptional Reagents:\nSpecialization:\nShaping - Glasswork (15)\n\nElemental Focusing Lens\nOptional Crafting Reagent\n+25 Recipe Difficulty\nProvides the following property: Your spells and abilities have a chance to deal bonus magic damage. The chosen school is based on socketed gems.\n\nUnique-Equipped: Embellished 2.\nUsable with: Khaz Algar recipes for most unembellished equipment.\n\"Can be bought and sold on the Auction House.\"" }
entries[435332] = { ["name"] = "Prismatic Null Stone", ["text"] = "2 sec cast\nTools: Jeweler's Tools\nReagents:\nNull Stone , Radiant Ruby , Extravagant Emerald , Stunning Sapphire , Ostentatious Onyx , Marbled Stone (15)\nOptional Reagents:\nSpecialization:\nShaping - Masonry (15)\n\nPrismatic Null Stone\nOptional Crafting Reagent\n+25 Recipe Difficulty\nProvides the following property: Increases effectiveness of Blasphemite secondary effects by 25%.\n\nUnique-Equipped: Embellished 2.\nUsable with: Khaz Algar recipes for most unembellished equipment.\n\"Can be bought and sold on the Auction House.\"" }
entries[435333] = { ["name"] = "Captured Starlight", ["text"] = "2 sec cast\nTools: Jeweler's Tools\nReagents:\nNull Stone , Ambivalent Amber (2), Inverted Prism\nOptional Reagents:\nVendor:\nLyrendal\nZone:\nDornogal\nCost:\n150\n\nCaptured Starlight\nOptional Crafting Reagent\n+25 Recipe Difficulty\nProvides the following property: When damaged at low health, unleash starlight to shield yourself. The frequency this can occur increases with socketed gems.\n\nUnique-Equipped: Embellished 2.\nUsable with: Khaz Algar recipes for most unembellished equipment.\n\"Can be bought and sold on the Auction House.\"" }
entries[435334] = { ["name"] = "Magnificent Jeweler's Setting", ["text"] = "2 sec cast 2\nTools: Jeweler's Tools\nReagents:\nNull Stone (2), Blasphemite , Marbled Stone (20)\nDrop:\nThe Silken Court\nZone:\nNerub-ar Palace\nRecipe:\nPurchasable on the Auction House\n\nMagnificent Jeweler's Setting\nUse: Add 1 socket to an amulet or ring. Cannot be used on PvP equipment.\n[\nJewelry can have up to 2 sockets.]" }
