entries[435382] = { ["name"] = "Binding of Binding", ["text"] = "2 sec cast 3\nTools: Jeweler's Tools\nReagents:\nBlasphemite , Ambivalent Amber (8), Null Stone , Crushed Gemstones (25), Spark (#256)\nOptional Reagents:\nDrop:\nThe Theater Troupe\n\nBinding of Binding\nBinds when picked up\nUnique-EquippedFinger\n+9,112 Stamina\n+ 2,450 Random Stat 1\n+ 2,450 Random Stat 2\nUse: Sever your bond at the cost of 1 Blasphemite. (2 Min Cooldown)\nEquip: Your spells and abilities have a chance to empower each unique gem color of an ally's socketed gems. This boon grants ( 1564 / 4) to each empowered secondary stat for 15 sec. This effect will always target your bonded ally, if able." }
entries[435383] = { ["name"] = "Fractured Gemstone Locket", ["text"] = "2 sec cast 3\nTools: Jeweler's Tools\nReagents:\nBlasphemite , Ambivalent Amber (8), Crushed Gemstones (25), Spark (#256)\nOptional Reagents:\nDelves:\nHeavy Trunk\n\nFractured Gemstone Locket\nBinds when picked up\nNeck\n+9,112 Stamina\n+ 2,450 Random Stat 1\n+ 2,450 Random Stat 2\nEquip: When you enter combat, gain 1 Dormant Gemstone per socketed gem.\n\nWhenever you heal an ally, bestow upon them 1 Empowered Gemstone to increase the potency of one of their socketed gems by 141 for 20 sec. When their gemstone becomes dormant, it is returned to you." }
